","import React, { useRef } from 'react';
import '@servicenow/now-scripting-ui-components' assert { external: 'uxasset' };
import { useRecord } from './hooks/useRecord.js';
import { useServiceNowEvent } from './utils/useServiceNowEvents.js';
import { setProperties } from './utils/setProperties.js';
import { ServiceNowEvents } from './utils/events.js';

/**
 * React wrapper for the `<now-record-common-ui-actionbar>` web component.
 *
 * This component displays ui and declarative actions for a record form.
 */
const FormActionBar = props => {
 const { onUiActionBarClicked, daModel, actionNodes } = props;
 const { actions } = useRecord();
 const elementRef = useRef(null);
 // Attach event listeners
 useServiceNowEvent(elementRef, ServiceNowEvents.FORM_ACTION_BAR.CLICKED, onUiActionBarClicked);
 // Set complex object properties directly on the element
 setProperties(elementRef, {
 actionNodes: actionNodes ?? actions.data?.actionNodes,
 daModel: daModel ?? actions.data?.daModel
 });
 if (!actions.data?.actionNodes) {
 return null;
 }
 return React.createElement("now-record-common-uiactionbar", { ref: elementRef });
};

