","import React, { useState, useEffect } from 'react';
import { NowRecordListConnected } from '@servicenow/react-components/NowRecordListConnected';
import { RecordProvider } from '@servicenow/react-components/RecordContext';
import { FormColumnLayout } from '@servicenow/react-components/FormColumnLayout';
import { FormActionBar } from '@servicenow/react-components/FormActionBar';

// 为了解决类型错误，暂时简化组件

export default function App() {
 const [currentView, setCurrentView] = useState('leave-requests');
 const [selectedRecord, setSelectedRecord] = useState(null);

 // 简化的导航函数
 const navigateToView = (view, id = null) => {
 const params = new URLSearchParams();
 params.set('view', view);
 if (id) params.set('id', id);

 const path = `${window.location.pathname}?${params.toString()}`;
 window.history.pushState({}, '', path);

 setCurrentView(view);
 if (id !== undefined) setSelectedRecord(id);
 };

 const renderContent = () => {
 switch (currentView) {
 case 'leave-requests':
 return (
 <LeaveRequestsList 
 onSelectRecord={(id) => navigateToView('detail', id)} 
 onNewRecord={() => navigateToView('create-leave')}
 />
 );
 case 'cancellations':
 return (
 <CancellationsList 
 onSelectRecord={(id) => navigateToView('detail', id)} 
 onNewRecord={() => navigateToView('create-cancellation')}
 />
 );
 case 'create-leave':
 return (
 <CreateLeaveRequest 
 onBack={() => navigateToView('leave-requests')} 
 />
 );
 case 'create-cancellation':
 return (
 <CreateCancellation 
 onBack={() => navigateToView('cancellations')}
 />
 );
 case 'detail':
 return (
 <RecordDetail 
 recordId={selectedRecord} 
 onBack={() => navigateToView('leave-requests')} 
 />
 );
 default:
 return <div>请假管理系统</div>;
 }
 };

 return (
 <div style={{ padding: '20px' }}>
 <h1>请假管理系统</h1>

 <div style={{ marginBottom: '20px' }}>
 <button 
 onClick={() => navigateToView('leave-requests')}
 style={{ margin: '5px' }}
 >
 请假申请
 </button>
 <button 
 onClick={() => navigateToView('cancellations')}
 style={{ margin: '5px' }}
 >
 销假申请
 </button>
 </div>

 <div>
 {renderContent()}
 </div>
 </div>
 );
}

function LeaveRequestsList({ onSelectRecord, onNewRecord }) {
 return (
 <div>
 <h2>请假申请列表</h2>
 <button onClick={onNewRecord} style={{ marginBottom: '10px' }}>
 新建请假申请
 </button>
 <NowRecordListConnected
 table="x_1973840_leave_request"
 listTitle="请假申请"
 columns="number,leave_type,start_date,end_date,leave_hours,approval_status"
 onRowClicked={(e) => onSelectRecord(e.detail.payload.sys_id)}
 onNewActionClicked={onNewRecord}
 />
 </div>
 );
}

function CancellationsList({ onSelectRecord, onNewRecord }) {
 return (
 <div>
 <h2>销假申请列表</h2>
 <button onClick={onNewRecord} style={{ marginBottom: '10px' }}>
 新建销假申请
 </button>
 <NowRecordListConnected
 table="x_1973840_leave_cancellation"
 listTitle="销假申请"
 columns="number,original_leave_request,cancel_start_date,cancel_end_date,cancel_hours,approval_status"
 onRowClicked={(e) => onSelectRecord(e.detail.payload.sys_id)}
 onNewActionClicked={onNewRecord}
 />
 </div>
 );
}

function CreateLeaveRequest({ onBack }) {
 return (
 <div>
 <h2>新建请假申请</h2>
 <button onClick={onBack} style={{ marginBottom: '10px' }}>
 返回
 </button>
 <RecordProvider table="x_1973840_leave_request" sysId="-1" isReadOnly={false}>
 <FormActionBar />
 <FormColumnLayout />
 </RecordProvider>
 </div>
 );
}

function CreateCancellation({ onBack }) {
 return (
 <div>
 <h2>新建销假申请</h2>
 <button onClick={onBack} style={{ marginBottom: '10px' }}>
 返回
 </button>
 <RecordProvider table="x_1973840_leave_cancellation" sysId="-1" isReadOnly={false}>
 <FormActionBar />
 <FormColumnLayout />
 </RecordProvider>
 </div>
 );
}

function RecordDetail({ recordId, onBack }) {
 if (!recordId) {
 return <div>未选择记录</div>;
 }

 return (
 <div>
 <h2>记录详情</h2>
 <button onClick={onBack} style={{ marginBottom: '10px' }}>
 返回
 </button>
 <RecordProvider table="x_1973840_leave_request" sysId={recordId} isReadOnly={false}>
 <FormActionBar />
 <FormColumnLayout />
 </RecordProvider>
 </div>
 );
}","import React from 'react';
import { createRoot } from 'react-dom/client';
import App from './app';

const container = document.getElementById('root');
if (container) {
 const root = createRoot(container);
 root.render(<App />);
